, author_id)\nVALUES (1, '敏感肌护理指南', '敏感肌的日常护理方法和注意事项', '敏感肌护理的核心是修护屏障，减少刺激。日常应选择温和的洁面产品，避免过度清洁。护肤步骤应简化，重点是保湿和修护。在选择产品时，应避免香精、酒精等刺激性成分。', 13, 'TEXT', 'https://cdn.example.com/cover/sensitive_skin.jpg', 1, 156, 3),\n       (2, '烟酰胺的功效与使用方法', '烟酰胺在护肤中的应用和注意事项', '烟酰胺是一种多功能成分，具有提亮肤色、修护屏障、控油等功效。使用浓度一般为2%-10%，初次使用建议从低浓度开始，逐渐建立耐受。', 22, 'PDF', 'https://cdn.example.com/cover/niacinamide.jpg', 1, 234, 1),\n       (3, '门店接待标准流程', '门店接待客户的标准流程和话术', '接待客户时应主动微笑，询问需求，了解客户的皮肤状况和护理历史。根据客户情况，推荐适合的项目和产品。', 31, 'TEXT', 'https://cdn.example.com/cover/reception.jpg', 1, 89, 3),\n       (4, '刷酸后护理指南', '刷酸后的护理方法和注意事项', '刷酸后皮肤会暂时变得敏感，需要加强保湿和防晒。避免使用刺激性产品，避免暴晒。', 41, 'PDF', 'https://cdn.example.com/cover/acid_peel.jpg', 1, 178, 1),\n       (5, '玻尿酸的保湿原理', '玻尿酸在护肤中的保湿机制', '玻尿酸是一种天然存在于人体中的多糖，具有强大的保湿能力。它可以吸收自身重量1000倍的水分，是理想的保湿成分。', 22, 'TEXT', 'https://cdn.example.com/